    g = [row[:] for row in grid]
    from collections import Counter
    counts = Counter(v for row in g for v in row)
    marker = min((v for v in counts if v not in (0, max(counts))), key=counts.get)
    # In these tasks the rare non-background, non-hole color marks the shape.
    coords = [(r, c) for r, row in enumerate(g) for c, v in enumerate(row) if v == marker]
    if not coords:
        return g
    r0, c0 = min(r for r, c in coords), min(c for r, c in coords)
    shape = {(r-r0, c-c0) for r, c in coords}
    sh, sw = max(r for r,c in shape)+1, max(c for r,c in shape)+1
    background = max((v for v in counts if v != marker), key=counts.get)
    for r in range(len(g)-sh+1):
        for c in range(len(g[0])-sw+1):
            if all(g[r+dr][c+dc] == (0 if (dr,dc) in shape else background)
                   for dr in range(sh) for dc in range(sw)):
                for dr, dc in shape:
                    g[r+dr][c+dc] = marker
    return g
